        cudaGetDevice(&dev);
        cudaDeviceGetAttribute(&numSM, cudaDevAttrMultiProcessorCount, dev);
    }
    int mb = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&mb, (void*)ln_coop_kernel, (int)threads, 0);
    return numSM * mb;
}

